#!/usr/bin/env bash
# Question 4: Frontend cannot reach ${Q4_APP}. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q4_NS}" --dry-run=client -o yaml | kubectl apply -f - >/dev/null
timeout 60 bash -c "until kubectl -n '${Q4_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: ${Q4_APP}
  namespace: ${Q4_NS}
spec:
  replicas: 2
  selector:
    matchLabels: { app: ${Q4_APP} }
  template:
    metadata:
      labels: { app: ${Q4_APP} }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
---
apiVersion: v1
kind: Service
metadata:
  name: ${Q4_APP}
  namespace: ${Q4_NS}
spec:
  selector: { app: ${Q4_APP} }
  ports: [{ port: 80, targetPort: 80 }]
---
apiVersion: v1
kind: Pod
metadata:
  name: client
  namespace: ${Q4_NS}
  labels: { role: frontend }
spec:
  containers:
    - name: shell
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: v1
kind: Pod
metadata:
  name: stranger
  namespace: ${Q4_NS}
  labels: { role: guest }
spec:
  containers:
    - name: shell
      image: busybox:1.36
      command: ["sleep", "infinity"]
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: default-deny
  namespace: ${Q4_NS}
spec:
  podSelector: {}
  policyTypes: [Ingress, Egress]
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: allow-dns
  namespace: ${Q4_NS}
spec:
  podSelector: {}
  policyTypes: [Egress]
  egress:
    - to:
        - namespaceSelector:
            matchLabels: { kubernetes.io/metadata.name: kube-system }
          podSelector:
            matchLabels: { k8s-app: kube-dns }
      ports:
        - { protocol: UDP, port: 53 }
        - { protocol: TCP, port: 53 }
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: frontend-egress
  namespace: ${Q4_NS}
spec:
  podSelector:
    matchLabels: { role: frontend }
  policyTypes: [Egress]
  egress:
    - to:
        - podSelector:
            matchLabels: { app: ${Q4_APP} }
      ports:
        - { protocol: TCP, port: 80 }
---
apiVersion: networking.k8s.io/v1
kind: NetworkPolicy
metadata:
  name: ${Q4_APP}-ingress
  namespace: ${Q4_NS}
spec:
  podSelector:
    matchLabels: { app: ${Q4_APP} }
  policyTypes: [Ingress]
  ingress:
    - from:
        - podSelector:
            matchLabels: { role: frontend }
      ports:
        - { protocol: TCP, port: 80 }
EOF
kubectl -n "${Q4_NS}" rollout status "deployment/${Q4_APP}" --timeout=240s
if ! kubectl -n "${Q4_NS}" wait --for=condition=Ready pod/client pod/stranger --timeout=180s; then
  kubectl -n "${Q4_NS}" describe pod client stranger >&2 || true
  exit 1
fi

case "${Q4_FAULT}" in
  dns-egress-port)
    kubectl -n "${Q4_NS}" patch networkpolicy "allow-dns" --type=json -p '[{"op":"replace","path":"/spec/egress/0/ports","value":[{"protocol":"UDP","port":5353},{"protocol":"TCP","port":5353}]}]'
    ;;
  dns-namespace-selector)
    kubectl -n "${Q4_NS}" patch networkpolicy "allow-dns" --type=json -p '[{"op":"replace","path":"/spec/egress/0/to/0/namespaceSelector/matchLabels","value":{"name":"kube-system"}}]'
    ;;
  ingress-port)
    kubectl -n "${Q4_NS}" patch networkpolicy "${Q4_APP}-ingress" --type=json -p '[{"op":"replace","path":"/spec/ingress/0/ports/0/port","value":8080}]'
    ;;
  ingress-from-label)
    kubectl -n "${Q4_NS}" patch networkpolicy "${Q4_APP}-ingress" --type=json -p '[{"op":"replace","path":"/spec/ingress/0/from/0/podSelector/matchLabels","value":{"role":"front-end"}}]'
    ;;
  egress-to-label)
    kubectl -n "${Q4_NS}" patch networkpolicy "frontend-egress" --type=json -p '[{"op":"replace","path":"/spec/egress/0/to/0/podSelector/matchLabels","value":{"app":"'"${Q4_APP}"'-v2"}}]'
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

# The question only makes sense if the client really is cut off.
for _ in $(seq 1 30); do
  kubectl -n "${Q4_NS}" exec client -- wget -qO- -T 3 "http://${Q4_APP}" 2>/dev/null | grep -q nginx || exit 0
  sleep 2
done
echo "the client can still reach ${Q4_APP}" >&2
exit 1
